/**
 * Recommend templates for a concrete product: keyword-signal hits (+2 each, format
 * built for the trait) stack with the goodFor category tie (+3), while templates
 * tuned for a DIFFERENT category are pushed down (-2). Pure and deterministic —
 * ties resolve by curated library order. Empty input → empty list (the UI hides
 * the row instead of showing fake "recommendations").
 */
export function recommendAdTemplates(
  input: { category?: string; productName?: string; sellingPoints?: string },
  limit = 4
): AdTemplate[] {
  const text = `${input.productName ?? ""} ${input.sellingPoints ?? ""}`.trim();
  const category = input.category;
  if (!text && !category) return [];
  const boosts = new Map<string, number>();
  if (text) {
    for (const rule of RECOMMEND_SIGNALS) {
      if (!rule.pattern.test(text)) continue;
      for (const id of rule.ids) boosts.set(id, (boosts.get(id) ?? 0) + 2);
    }
  }
  const scored = AD_TEMPLATES.map((t, i) => {
    let score = boosts.get(t.id) ?? 0;
    if (category && t.goodFor) score += t.goodFor.includes(category as AdTemplateCategory) ? 3 : -2;
    return { t, score, i };
  }).filter((s) => s.score > 0);
  scored.sort((a, b) => b.score - a.score || a.i - b.i);
  return scored.slice(0, limit).map((s) => s.t);
}

/* ==================== AI-generated custom template ==================== */

/** Fixed id for the per-project AI-generated template (only one custom slot per project). */
export const CUSTOM_AD_TEMPLATE_ID = "custom_ai";

const STYLE_VALUES = new Set([
  "drama", "reversal", "interview", "story", "unboxing", "product_pov",
  "comparison", "talking_head", "pain-point", "scenario", "auto",
]);
const VIDEO_MODES = new Set(["product_closeup", "graphic_montage", "scene_demo", "live_presenter"]);
const BGM_VALUES = new Set(["none", "upbeat", "chill", "energetic", "emotional"]);
const QUALITY_VALUES = new Set(["fast", "standard", "hd"]);
const SHOT_TYPES = new Set(["hook", "pain_point", "product_reveal", "demo", "social_proof", "cta"]);
const GROUP_BY_MODE: Record<AdTemplate["videoMode"], AdTemplateGroupId> = {
  product_closeup: "product_show",
  graphic_montage: "creative",
  scene_demo: "lifestyle",
  live_presenter: "presenter",
};

/**
 * Clamp an LLM-produced template object into a guaranteed-valid AdTemplate.
 * Every field is validated against the real preset vocabularies; anything invalid
 * falls back to a safe default instead of failing — the LLM's creative intent
 * survives where it was legal, and the pipeline never receives an unknown id.
 * Returns null only when the input is not an object at all.
 */
export function sanitizeCustomAdTemplate(raw: unknown): AdTemplate | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  const str = (v: unknown, max = 120): string => (typeof v === "string" ? v.trim().slice(0, max) : "");
  const nameRaw = (r.name ?? {}) as Record<string, unknown>;
  const taglineRaw = (r.tagline ?? {}) as Record<string, unknown>;
  const hintRaw = (r.scriptHint ?? {}) as Record<string, unknown>;
  const nameZh = str(nameRaw.zh, 24) || "AI定制模板";
  const nameEn = str(nameRaw.en, 48) || "AI Custom";

  const videoMode = (VIDEO_MODES.has(String(r.videoMode)) ? String(r.videoMode) : "product_closeup") as AdTemplate["videoMode"];
  const groupRaw = String(r.group ?? "");
  const group = (AD_TEMPLATE_GROUPS.some((g) => g.id === groupRaw) ? groupRaw : GROUP_BY_MODE[videoMode]) as AdTemplateGroupId;

  const cameraPlan: Partial<Record<Shot["type"], string>> = {};
  if (r.cameraPlan && typeof r.cameraPlan === "object") {
    for (const [type, presetId] of Object.entries(r.cameraPlan as Record<string, unknown>)) {
      if (SHOT_TYPES.has(type) && typeof presetId === "string" && getCameraPreset(presetId)) {
        cameraPlan[type as Shot["type"]] = presetId;
      }
    }
  }
  if (Object.keys(cameraPlan).length < 2) {
    Object.assign(cameraPlan, { hook: "crash_push", product_reveal: "orbit_slow", demo: "macro_glide", cta: "push_then_hold" });
  }

  const composeRaw = (r.compose ?? {}) as Record<string, unknown>;
  const compose: StylePackCompose = {
    captionPreset: isCaptionPreset(composeRaw.captionPreset) ? composeRaw.captionPreset : "standard",
    bgm: BGM_VALUES.has(String(composeRaw.bgm)) ? (String(composeRaw.bgm) as StylePackCompose["bgm"]) : "upbeat",
    bgmDuck: typeof composeRaw.bgmDuck === "boolean" ? composeRaw.bgmDuck : true,
    ...(QUALITY_VALUES.has(String(composeRaw.quality)) && { quality: String(composeRaw.quality) as StylePackCompose["quality"] }),
    ...(typeof composeRaw.productCard === "boolean" && { productCard: composeRaw.productCard }),
  };

  const goodFor = Array.isArray(r.goodFor)
    ? (r.goodFor.filter((c) => ["beauty", "food", "home", "fashion", "digital"].includes(String(c))) as AdTemplateCategory[])
    : [];

  return {
    id: CUSTOM_AD_TEMPLATE_ID,
    emoji: str(r.emoji, 8) || "✨",
    name: { zh: nameZh, en: nameEn },
    tagline: {
      zh: str(taglineRaw.zh, 60) || "AI 按你的商品定制的成片配方",
      en: str(taglineRaw.en, 120) || "An AI-tailored recipe for this product",
    },
    group,
    ...(goodFor.length > 0 && { goodFor }),
    styleType: STYLE_VALUES.has(String(r.styleType)) ? String(r.styleType) : "pain-point",
    videoMode,
    look: getLookPreset(str(r.look)) ? str(r.look) : "daylight_clean",
    cameraPlan,
    compose,
    scriptHint: { zh: str(hintRaw.zh, 300) || "围绕商品核心卖点展开，节奏紧凑，画面与口播互补" },
  };
}

/** Stored-value prefix marking an inline custom template (vs. a builtin id). */
const CUSTOM_STORED_PREFIX = "custom:";

/**
 * Encode a template selection for localStorage: builtin → its id, everything else
 * (AI custom AND user-owned "my templates") → inline JSON. Deciding by library
 * lookup instead of the custom-id sentinel matters: a my-template id stored bare
 * would be unresolvable on decode (it only exists in the DB, not in this module).
 */
export function encodeStoredAdTemplate(template: AdTemplate): string {
  return getAdTemplate(template.id)
    ? template.id
    : CUSTOM_STORED_PREFIX + JSON.stringify(template);
}

/** Decode a stored selection back to a template (builtin lookup or sanitized inline custom). */
export function decodeStoredAdTemplate(raw: string | null | undefined): AdTemplate | undefined {
  if (!raw) return undefined;
  if (raw.startsWith(CUSTOM_STORED_PREFIX)) {
    try {
      return sanitizeCustomAdTemplate(JSON.parse(raw.slice(CUSTOM_STORED_PREFIX.length))) ?? undefined;
    } catch {
      return undefined;
    }
  }
  return getAdTemplate(raw);
}

/** Shot-type labels for the camera-plan directive (script-facing, Chinese prompt). */
const PLAN_TYPE_LABELS: Record<string, string> = {
  hook: "钩子镜(hook)",
  pain_point: "痛点镜(pain_point)",
  product_reveal: "商品镜(product_reveal)",
  demo: "演示镜(demo)",
  social_proof: "背书镜(social_proof)",
  cta: "转化镜(cta)",
};

/**
 * The template's creative direction block for the script LLM, appended as a custom
 * requirement: look direction + per-shot-type camera sentences resolved from the
 * preset library. The LLM writes these into `Shot.camera`, so the plan flows through
 * the motion-prompt engine with zero extra plumbing — and stays per-shot editable.
 */
export function adTemplateScriptDirective(template: AdTemplate): string {
  const lines: string[] = [];
  const look = getLookPreset(template.look);
  lines.push(`【成片模板：${template.name.zh}】${template.scriptHint.zh}。`);
  if (look) lines.push(`画面光线与色调统一为「${look.name.zh}」：${look.image.zh}。`);
  const planLines = Object.entries(template.cameraPlan)
    .map(([type, presetId]) => {
      const preset = presetId ? getCameraPreset(presetId) : undefined;
      if (!preset) return null;
      return `${PLAN_TYPE_LABELS[type] ?? type} 的 camera 写「${preset.prompt.zh}」`;
    })
    .filter(Boolean);
  if (planLines.length > 0) {
    lines.push(`运镜编排（对应类型的分镜按此填写 camera 字段）：${planLines.join("；")}。`);
  }
  return lines.join("");
}

/** localStorage key carrying a project's chosen ad template (client-side, same convention as template store). */
export function adTemplateStorageKey(projectId: string): string {
  return `mora-ad-template:${projectId}`;
}

/** localStorage key marking that the video page already applied the template's compose recipe once. */
export function adTemplateAppliedKey(projectId: string): string {
  return `mora-ad-template-applied:${projectId}`;
}

/* ==================== Shareable recipe format (template economy) ==================== */

/**
 * A template is a recipe, and recipes are meant to travel — the ComfyUI/n8n
 * playbook where shareable configs become community currency. This block defines
 * the interchange format: a small JSON envelope around one AdTemplate. Exports
 * strip the id (the importer mints its own); imports are clamped by
 * sanitizeCustomAdTemplate (unknown ids degrade to safe defaults, so a file from
 * a future version with new presets still lands usable) and screened against the
 * ad-law lexicon. Lexicon hits surface as WARNINGS, never rejections: a template
 * is a creative directive, not published copy — guardrail sentences like
 * "不得宣称疗效" and aesthetic idioms like "治愈系" hit the same terms as real
 * violations (14 of our own curated 391 match), so word-level rejection here is
 * all false positives. The hard gate stays where context is real: the compose
 * stage scans the actual voiceover/captions of the finished video.
 */
export const AD_TEMPLATE_SHARE_KIND = "mora-ad-template";
export const AD_TEMPLATE_SHARE_VERSION = 1;

export type AdTemplateShareError =
  | "invalid_json"
  | "wrong_kind"
  | "unsupported_version"
  | "invalid_template";

export interface AdTemplateShareResult {
  template?: AdTemplate;
  error?: AdTemplateShareError;
  /** Ad-law lexicon hits in the recipe text — shown to the user, never blocking */
  warnings?: string[];
}

/** Serialize a template as a shareable JSON document (id stripped; pretty-printed for hand editing). */
export function exportAdTemplateShare(template: AdTemplate): string {
  const recipe: Partial<AdTemplate> = { ...template };
  delete recipe.id;
  return JSON.stringify(
    { kind: AD_TEMPLATE_SHARE_KIND, version: AD_TEMPLATE_SHARE_VERSION, template: recipe },
    null,
    2
  );
}

/** Parse + validate + compliance-screen a shared template JSON string. */
export function parseAdTemplateShare(raw: string): AdTemplateShareResult {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return { error: "invalid_json" };
  }
  const envelope = parsed as { kind?: unknown; version?: unknown; template?: unknown } | null;
  if (!envelope || envelope.kind !== AD_TEMPLATE_SHARE_KIND) return { error: "wrong_kind" };
  if (envelope.version !== AD_TEMPLATE_SHARE_VERSION) return { error: "unsupported_version" };
  const template = sanitizeCustomAdTemplate(envelope.template);
  if (!template) return { error: "invalid_template" };
  const warnings = complianceTerms(template);
  return { template, ...(warnings.length > 0 && { warnings }) };
}

/** Ad-law lexicon hits in one template's recipe copy (shared by single + pack parsing). */
function complianceTerms(template: AdTemplate): string[] {
  return checkAdCompliance(
    [template.name.zh, template.tagline.zh, template.scriptHint.zh].join(" \n ")
  ).map((v) => v.term);
}

/* ==================== Multi-template pack ==================== */

export const AD_TEMPLATE_PACK_KIND = "mora-ad-template-pack";
/** Hard ceiling on pack size — entries past it are dropped (protects the DB from a hostile multi-megabyte file). */
const AD_TEMPLATE_PACK_MAX = 100;

export interface AdTemplatePackResult {
  templates?: AdTemplate[];
  error?: AdTemplateShareError;
  /** Ad-law lexicon hits across ALL entries, deduplicated — shown to the user, never blocking */
  warnings?: string[];
}

/** Serialize several templates as one shareable pack document (ids stripped, like the single format). */
export function exportAdTemplatePack(templates: AdTemplate[]): string {
  const recipes = templates.map((t) => {
    const recipe: Partial<AdTemplate> = { ...t };
    delete recipe.id;
    return recipe;
  });
  return JSON.stringify(
    { kind: AD_TEMPLATE_PACK_KIND, version: AD_TEMPLATE_SHARE_VERSION, templates: recipes },
    null,
    2
  );
}

/**
 * Parse a share document of EITHER kind — one template or a pack — behind the
 * same paste box. Pack entries are clamped individually; entries that are not
 * objects at all are dropped, and the parse fails only when nothing usable
 * remains. Warnings are the union across entries.
 */
export function parseAdTemplateShareAny(raw: string): AdTemplatePackResult {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return { error: "invalid_json" };
  }
  const envelope = parsed as
    | { kind?: unknown; version?: unknown; template?: unknown; templates?: unknown }
    | null;
  if (!envelope || (envelope.kind !== AD_TEMPLATE_SHARE_KIND && envelope.kind !== AD_TEMPLATE_PACK_KIND)) {
    return { error: "wrong_kind" };
  }
  if (envelope.version !== AD_TEMPLATE_SHARE_VERSION) return { error: "unsupported_version" };
  const entries =
    envelope.kind === AD_TEMPLATE_PACK_KIND
      ? Array.isArray(envelope.templates)
        ? envelope.templates
        : []
      : [envelope.template];
  const templates = entries
    .slice(0, AD_TEMPLATE_PACK_MAX)
    .map((entry) => sanitizeCustomAdTemplate(entry))
    .filter((t): t is AdTemplate => t !== null);
  if (templates.length === 0) return { error: "invalid_template" };
  const warnings = [...new Set(templates.flatMap(complianceTerms))];
  return { templates, ...(warnings.length > 0 && { warnings }) };
}

/**
 * Recipe-editor select vocabularies — spread from the very sets
 * sanitizeCustomAdTemplate clamps against, so the editor can never offer a
 * value the validator would reject.
 */
export const AD_TEMPLATE_EDIT_VOCAB = {
  bgm: [...BGM_VALUES] as NonNullable<StylePackCompose["bgm"]>[],
  quality: [...QUALITY_VALUES] as NonNullable<StylePackCompose["quality"]>[],
  shotTypes: [...SHOT_TYPES] as Shot["type"][],
};
